from collections import deque
def objects(g):
    h,w=len(g),len(g[0])
    seen=set(); objs=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] not in (0,2) and (i,j) not in seen:
                col=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and (x,y) not in seen and g[x][y]==col:
                            seen.add((x,y)); q.append((x,y))
                objs.append((col,cells))
    return objs

def transform(g):
    h,w=len(g),len(g[0])
    b=next(i for i,r in enumerate(g) if all(x==2 for x in r))
    down = b==h-1
    step = -1 if down else 1
    out=[[2 if x==2 else 0 for x in r] for r in g]
    objs=objects(g)
    def free(col,cells):
        return all(0<=x<h and out[x][y] in (0,) for x,y in cells)
    for col,cells in objs:
        assert free(col,cells)
        for x,y in cells: out[x][y]=0
    moved=True
    while moved:
        moved=False
        for k,(col,cells) in enumerate(objs):
            nc=[(x+step,y) for x,y in cells]
            if all(0<=x<h for x,_ in nc) and all(out[x][y]==0 for x,y in nc):
                objs[k]=(col,nc); moved=True
    for col,cells in objs:
        for x,y in cells: out[x][y]=col
    return out
